"""Offline temporal analysis and bounded visual exports for perception JSONL."""
from collections import defaultdict
import json
from pathlib import Path

import cv2
import numpy as np


CLASS_NAMES = ("road", "W_line", "Y_line", "R_light", "Y_light",
               "G_light", "Left", "etc_light", "stop", "traffic20",
               "C_line", "words")
LIGHT_CLASSES = frozenset(("R_light", "Y_light", "G_light", "Left", "etc_light"))


def load_records(path):
    records = []
    with Path(path).open(encoding="utf-8") as stream:
        for line in stream:
            if line.strip():
                records.append(json.loads(line))
    records.sort(key=lambda item: (item.get("video_frame_index") is None,
                                   item.get("video_frame_index", 0)))
    return records


def confidence_summary(values):
    if not values:
        return {key: None for key in ("mean", "median", "p05", "p95",
                                      "min", "max", "std")}
    array = np.asarray(values, dtype=float)
    return {"mean": float(array.mean()), "median": float(np.median(array)),
            "p05": float(np.percentile(array, 5)),
            "p95": float(np.percentile(array, 95)), "min": float(array.min()),
            "max": float(array.max()), "std": float(array.std())}


def continuous_runs(indices):
    if not indices:
        return []
    runs, start, previous = [], indices[0], indices[0]
    for current in indices[1:]:
        if current != previous + 1:
            runs.append((start, previous))
            start = current
        previous = current
    runs.append((start, previous))
    return runs


def gap_candidates(indices, maximum_gap=5):
    return [{"start": left + 1, "end": right - 1, "length": right-left-1}
            for left, right in zip(indices, indices[1:])
            if 1 < right-left <= maximum_gap+1]


def _frame_index(record, fallback):
    value = record.get("video_frame_index")
    return fallback if value is None else int(value)


def class_statistics(records):
    output = {}
    for name in CLASS_NAMES:
        frames, confidences, counts, areas = [], [], [], []
        for offset, record in enumerate(records):
            detections = [item for item in record.get("detections", [])
                          if item.get("class_name") == name]
            if detections:
                frames.append(_frame_index(record, offset))
                confidences.extend(float(item["confidence"]) for item in detections)
                counts.append(len(detections))
            metric = record.get("semantic_masks", {}).get(name)
            if metric is not None:
                areas.append(float(metric["area_ratio"]))
        runs = continuous_runs(frames)
        output[name] = {
            "detection_frames": len(frames), "total_instances": len(confidences),
            "first_detected_frame": None if not frames else frames[0],
            "last_detected_frame": None if not frames else frames[-1],
            "confidence": confidence_summary(confidences),
            "confidence_bins": {
                "0.25_0.30": sum(.25 <= value < .30 for value in confidences),
                "0.30_0.40": sum(.30 <= value < .40 for value in confidences),
                "0.40_0.60": sum(.40 <= value < .60 for value in confidences),
                "0.60_plus": sum(value >= .60 for value in confidences),
            },
            "instance_count_mean": None if not counts else float(np.mean(counts)),
            "instance_count_max": 0 if not counts else int(max(counts)),
            "longest_continuous_run": 0 if not runs else
                max(end-start+1 for start, end in runs),
            "temporal_gap_candidates": gap_candidates(frames),
            "mask_area_ratio": confidence_summary(areas),
            "presence": ("UNKNOWN_REQUIRES_HUMAN_REVIEW" if not frames else
                         "PRESENT_BUT_REQUIRES_HUMAN_REVIEW"),
        }
    return output


def rank_anomalies(records, limit=100):
    anomalies = []
    previous = {}
    for offset, record in enumerate(records):
        frame = _frame_index(record, offset)
        grouped = defaultdict(list)
        for detection in record.get("detections", []):
            grouped[detection.get("class_name")].append(detection)
        for name in CLASS_NAMES:
            confidences = [float(item["confidence"]) for item in grouped[name]]
            state = {"count": len(confidences),
                     "confidence": max(confidences) if confidences else None}
            metric = record.get("semantic_masks", {}).get(name)
            state["area"] = None if metric is None else float(metric["area_ratio"])
            old = previous.get(name)
            if old is not None:
                if abs(state["count"]-old["count"]) >= 3:
                    anomalies.append({"priority": 4, "frame": frame, "class": name,
                                      "reason": "instance_count_jump",
                                      "score": abs(state["count"]-old["count"])})
                if state["confidence"] is not None and old["confidence"] is not None:
                    delta = abs(state["confidence"]-old["confidence"])
                    if delta >= .25:
                        anomalies.append({"priority": 2, "frame": frame,
                                          "class": name,
                                          "reason": "confidence_jump", "score": delta})
                if state["area"] is not None and old["area"] is not None:
                    delta = abs(state["area"]-old["area"])
                    if delta >= .05:
                        anomalies.append({"priority": 3, "frame": frame,
                                          "class": name,
                                          "reason": "mask_area_jump", "score": delta})
                if old["count"] and not state["count"]:
                    anomalies.append({"priority": 5, "frame": frame, "class": name,
                                      "reason": "temporary_disappearance", "score": 1})
                if not old["count"] and state["count"]:
                    anomalies.append({"priority": 5, "frame": frame, "class": name,
                                      "reason": "sudden_appearance", "score": 1})
            previous[name] = state
    anomalies.sort(key=lambda item: (item["priority"], -item["score"], item["frame"]))
    return anomalies[:limit]


def _bbox_iou(left, right):
    x1, y1 = max(left[0], right[0]), max(left[1], right[1])
    x2, y2 = min(left[2], right[2]), min(left[3], right[3])
    intersection = max(0.0, x2-x1) * max(0.0, y2-y1)
    union = ((left[2]-left[0])*(left[3]-left[1]) +
             (right[2]-right[0])*(right[3]-right[1]) - intersection)
    return 0.0 if union <= 0.0 else intersection/union


def traffic_light_transitions(records):
    transitions = []
    for offset, (left, right) in enumerate(zip(records, records[1:]), start=1):
        before = [item for item in left.get("detections", [])
                  if item.get("class_name") in LIGHT_CLASSES]
        after = [item for item in right.get("detections", [])
                 if item.get("class_name") in LIGHT_CLASSES]
        for old in before:
            for new in after:
                if (old["class_name"] != new["class_name"] and
                        _bbox_iou(old["xyxy"], new["xyxy"]) >= .1):
                    transitions.append({"frame": _frame_index(right, offset),
                                        "from": old["class_name"],
                                        "to": new["class_name"],
                                        "spatial_iou": _bbox_iou(old["xyxy"], new["xyxy"])})
    return transitions


def select_representatives(records, per_class=8):
    selected = {}
    for name in CLASS_NAMES:
        candidates = []
        for offset, record in enumerate(records):
            items = [item for item in record.get("detections", [])
                     if item.get("class_name") == name]
            if items:
                candidates.append((_frame_index(record, offset), record, items))
        if not candidates:
            selected[name] = []
            continue
        choices = [candidates[0], candidates[-1],
                   max(candidates, key=lambda item: max(x["confidence"] for x in item[2])),
                   min(candidates, key=lambda item: min(x["confidence"] for x in item[2])),
                   max(candidates, key=lambda item: len(item[2]))]
        stride = max(1, len(candidates)//max(1, per_class-len(choices)))
        choices.extend(candidates[::stride])
        unique = {}
        for choice in choices:
            unique[choice[0]] = choice
        selected[name] = list(unique.values())[:per_class]
    return selected


def _annotate(frame, record, focus=None):
    output = frame.copy()
    for item in record.get("detections", []):
        if focus is not None and item.get("class_name") != focus:
            continue
        x1, y1, x2, y2 = map(lambda value: int(round(value)), item["xyxy"])
        cv2.rectangle(output, (x1, y1), (x2, y2), (0, 220, 255), 2)
        cv2.putText(output, f'{item["class_name"]} {item["confidence"]:.2f}',
                    (max(0, x1), max(18, y1-4)), cv2.FONT_HERSHEY_SIMPLEX,
                    .5, (0, 0, 0), 3, cv2.LINE_AA)
        cv2.putText(output, f'{item["class_name"]} {item["confidence"]:.2f}',
                    (max(0, x1), max(18, y1-4)), cv2.FONT_HERSHEY_SIMPLEX,
                    .5, (0, 220, 255), 1, cv2.LINE_AA)
    cv2.putText(output, f'frame {_frame_index(record, 0)}', (8, 20),
                cv2.FONT_HERSHEY_SIMPLEX, .55, (255, 255, 255), 2, cv2.LINE_AA)
    return output


def export_visuals(video_path, records, representatives, anomalies, output_dir):
    output_dir = Path(output_dir)
    representative_root = output_dir/"representative_frames"
    anomaly_root = output_dir/"anomaly_frames"
    sheets_root = output_dir/"contact_sheets"
    for directory in (representative_root, anomaly_root, sheets_root):
        directory.mkdir(parents=True, exist_ok=True)
    by_index = {_frame_index(record, offset): record
                for offset, record in enumerate(records)}
    wanted = set()
    for choices in representatives.values():
        wanted.update(choice[0] for choice in choices)
    for anomaly in anomalies[:30]:
        wanted.update(range(max(0, anomaly["frame"]-2), anomaly["frame"]+3))
    capture = cv2.VideoCapture(str(video_path))
    decoded = {}
    for index in sorted(wanted):
        capture.set(cv2.CAP_PROP_POS_FRAMES, float(index))
        ok, frame = capture.read()
        if ok:
            decoded[index] = cv2.resize(frame, (640, 480), interpolation=cv2.INTER_AREA)
    capture.release()
    saved = defaultdict(list)
    for name, choices in representatives.items():
        directory = representative_root/name
        directory.mkdir(parents=True, exist_ok=True)
        for index, record, _ in choices:
            if index not in decoded:
                continue
            path = directory/f"frame_{index:06d}.jpg"
            cv2.imwrite(str(path), _annotate(decoded[index], record, name))
            saved[name].append(path)
    for rank, anomaly in enumerate(anomalies[:30], start=1):
        directory = anomaly_root/f"{rank:03d}_{anomaly['class']}_{anomaly['reason']}"
        directory.mkdir(parents=True, exist_ok=True)
        for index in range(max(0, anomaly["frame"]-2), anomaly["frame"]+3):
            if index in decoded and index in by_index:
                cv2.imwrite(str(directory/f"frame_{index:06d}.jpg"),
                            _annotate(decoded[index], by_index[index]))
    sheets = {}
    for name, paths in saved.items():
        images = [cv2.imread(str(path)) for path in paths[:12]]
        images = [image for image in images if image is not None]
        if not images:
            continue
        thumbs = [cv2.resize(image, (320, 240)) for image in images]
        while len(thumbs) % 4:
            thumbs.append(np.zeros_like(thumbs[0]))
        sheet = np.vstack([np.hstack(thumbs[row:row+4])
                           for row in range(0, len(thumbs), 4)])
        path = sheets_root/f"{name}_contact_sheet.jpg"
        cv2.imwrite(str(path), sheet)
        sheets[name] = str(path)
    light_paths = [path for name in LIGHT_CLASSES for path in saved.get(name, [])]
    images = [cv2.imread(str(path)) for path in light_paths[:12]]
    images = [image for image in images if image is not None]
    if images:
        thumbs = [cv2.resize(image, (320, 240)) for image in images]
        while len(thumbs) % 4:
            thumbs.append(np.zeros_like(thumbs[0]))
        path = sheets_root/"traffic_light_contact_sheet.jpg"
        cv2.imwrite(str(path), np.vstack([
            np.hstack(thumbs[row:row+4]) for row in range(0, len(thumbs), 4)]))
        sheets["traffic_light"] = str(path)
    return {"representative_files": {key: [str(path) for path in value]
                                     for key, value in saved.items()},
            "contact_sheets": sheets}


def write_report(path, metadata, statistics, anomalies, transitions, visuals):
    lines = ["# YOLO-Seg Perception Validation", "",
             "## Automatically measured", "",
             f"- Processed inference frames: {metadata.get('processed_frames', 0)}",
             f"- Traffic-light transition candidates: {len(transitions)}",
             f"- Ranked anomaly candidates: {len(anomalies)}", "",
             "## Class statistics", ""]
    for name in CLASS_NAMES:
        item = statistics[name]
        lines.extend((f"### {name}", "",
                      f"- Detection frames: {item['detection_frames']}",
                      f"- Instances: {item['total_instances']}",
                      f"- Longest run: {item['longest_continuous_run']}",
                      f"- Gap candidates: {len(item['temporal_gap_candidates'])}",
                      f"- Presence: {item['presence']}", ""))
    lines.extend(("## Human review required", "",
                  "Automatic candidates are not ground-truth false positives or false negatives.",
                  "Review representative frames, anomaly sequences, and the full annotated video.", ""))
    Path(path).write_text("\n".join(lines), encoding="utf-8")


def analyze(metadata_path, video_path, output_dir):
    output_dir = Path(output_dir); output_dir.mkdir(parents=True, exist_ok=True)
    records = load_records(metadata_path)
    statistics = class_statistics(records)
    anomalies = rank_anomalies(records)
    transitions = traffic_light_transitions(records)
    representatives = select_representatives(records)
    visuals = export_visuals(video_path, records, representatives, anomalies, output_dir)
    (output_dir/"class_statistics.json").write_text(
        json.dumps(statistics, indent=2)+"\n", encoding="utf-8")
    temporal = {name: {"longest_continuous_run": item["longest_continuous_run"],
                       "gap_candidates": item["temporal_gap_candidates"],
                       "confidence": item["confidence"],
                       "mask_area_ratio": item["mask_area_ratio"]}
                for name, item in statistics.items()}
    (output_dir/"temporal_statistics.json").write_text(
        json.dumps(temporal, indent=2)+"\n", encoding="utf-8")
    anomaly_report = {"ranked_anomalies": anomalies,
                      "traffic_light_transition_candidates": transitions}
    (output_dir/"anomaly_report.json").write_text(
        json.dumps(anomaly_report, indent=2)+"\n", encoding="utf-8")
    metadata = {"processed_frames": len(records)}
    write_report(output_dir/"validation_report.md", metadata, statistics,
                 anomalies, transitions, visuals)
    return {"records": len(records), "statistics": statistics,
            "anomalies": anomalies, "transitions": transitions, **visuals}
